	private static final class ArrayIntersection implements NativeLmdbQuerySource.NodeDomainIntersection {

		private final long[] values;

		private ArrayIntersection(long[] left, long[] right) {
			long[] intersection = new long[Math.min(left.length, right.length)];
			int size = 0;
			for (long candidate : left) {
				if (contains(right, candidate)) {
					intersection[size++] = candidate;
				}
			}
			values = Arrays.copyOf(intersection, size);
		}

		@Override
		public long estimatedWork() {
			return values.length;
		}

		@Override
		public int partitionCount() {
			return values.length;
		}

		@Override
		public long countPartition(int partition) {
			return 1L;
		}

		@Override
		public Cursor cursor(int partition) {
			return new Cursor() {
				private boolean available = true;

				@Override
				public boolean next() {
					boolean next = available;
					available = false;
					return next;
				}

				@Override
				public long nodeId() {
					return values[partition];
				}
			};
		}

		@Override
		public boolean contains(long candidate) {
			return contains(values, candidate);
		}

		private static boolean contains(long[] candidates, long target) {
			for (long candidate : candidates) {
				if (candidate == target) {
					return true;
				}
			}
			return false;
		}
	}

	private static final class ParallelOpeningSource extends StubSource {

		final boolean active;
		final boolean failIfOpened;
		final IOException openFailure;
		final NativeLmdbQuerySource.ParallelSource[] children;
		int parallelOpenCalls;

		private ParallelOpeningSource(Object idSpace, boolean active, boolean failIfOpened, IOException openFailure,
				NativeLmdbQuerySource.ParallelSource[] children) {
			super(idSpace);
			this.active = active;
			this.failIfOpened = failIfOpened;
			this.openFailure = openFailure;
			this.children = children;
		}

		static ParallelOpeningSource active(Object idSpace, NativeLmdbQuerySource.ParallelSource... children) {
			return new ParallelOpeningSource(idSpace, true, false, null, children);
		}

		static ParallelOpeningSource inactive(Object idSpace) {
			return new ParallelOpeningSource(idSpace, false, true, null,
					new NativeLmdbQuerySource.ParallelSource[0]);
		}

		static ParallelOpeningSource failing(Object idSpace, IOException openFailure) {
			return new ParallelOpeningSource(idSpace, true, false, openFailure,
					new NativeLmdbQuerySource.ParallelSource[0]);
		}

		@Override
		public ParallelSource[] openParallelSources(int count) throws IOException {
			parallelOpenCalls++;
			if (failIfOpened) {
				throw new AssertionError("inactive source must not open parallel siblings");
			}
			if (openFailure != null) {
				throw openFailure;
			}
			if (children.length != count) {
				throw new AssertionError("expected " + children.length + " parallel siblings, got " + count);
			}
			return children;
		}

		@Override
		public boolean hasStatementsInSource() {
			return active;
		}
	}

	private static final class SnapshotEpoch {
		long value = 1L;
	}

	private static final class SnapshotOpeningSource extends StubSource {

		final SnapshotEpoch epoch;
		final boolean advanceAfterOpen;
		final List<SnapshotParallelSource> children = new ArrayList<>();
		int parallelOpenCalls;

		SnapshotOpeningSource(Object idSpace, SnapshotEpoch epoch, boolean advanceAfterOpen) {
			super(idSpace);
			this.epoch = epoch;
			this.advanceAfterOpen = advanceAfterOpen;
		}

		@Override
		public ParallelSource[] openParallelSources(int count) {
			parallelOpenCalls++;
			long snapshotId = epoch.value;
			ParallelSource[] opened = new ParallelSource[count];
			for (int i = 0; i < count; i++) {
				SnapshotParallelSource child = new SnapshotParallelSource(idSpace, snapshotId);
				children.add(child);
				opened[i] = child;
			}
			if (advanceAfterOpen) {
				epoch.value++;
			}
			return opened;
		}
	}

